<script setup lang="ts">import{onMounted,onBeforeUnmount,reactive,ref,computed}from'vue';import{useRoute,useRouter}from'vue-router';import{wmApi}from'../api';import{ApiError,newsStatus,statusLabel,streamPost,useAuthStore,type Channel,type ContentBlock,type Material,type WmNews}from'@leadnews/shared';import{ElMessage}from'element-plus';const route=useRoute(),router=useRouter(),auth=useAuthStore(),id=computed(()=>Number(route.params.id)||0),channels=ref<Channel[]>([]),materials=ref<Material[]>([]),news=ref<WmNews>(),saving=ref(false),ai=reactive({instruction:'请延续当前文章的语气和主题',targetLength:300,text:'',state:'idle'}),controller=ref<AbortController>();const apiBase=(import.meta.env.VITE_API_BASE_URL as string).replace(/\/$/,'');const form=reactive({title:'',channelId:undefined as number|undefined,labels:'',layout:0,publishTime:'',content:[{type:'text',value:''}] as ContentBlock[],coverImages:[] as string[],materialIds:[] as number[]});const editable=computed(()=>!news.value||['DRAFT','REJECTED'].includes(news.value.status));function fill(n:WmNews){news.value=n;Object.assign(form,{title:n.title,channelId:n.channelId,labels:n.labels||'',layout:n.layout,publishTime:n.publishTime||'',content:n.content.length?n.content:[{type:'text',value:''}],coverImages:n.coverImages||[]})}async function save(){saving.value=true;try{const body={...form,publishTime:form.publishTime||null};const n=id.value?await wmApi.update(id.value,body):await wmApi.create(body);fill(n);ElMessage.success('已保存');if(!id.value)router.replace(`/news/${n.id}`)}catch(e){ElMessage.error(e instanceof ApiError?e.message:'保存失败')}finally{saving.value=false}}async function submit(){await save();if(news.value){fill(await wmApi.submit(news.value.id));ElMessage.success('已提交审核')}}function add(type:'text'|'image'){form.content.push({type,value:''})}function remove(i:number){form.content.splice(i,1)}function useMaterial(m:Material){form.content.push({type:'image',value:m.url});if(!form.materialIds.includes(m.id))form.materialIds.push(m.id)}async function generate(){if(!id.value)return void ElMessage.warning('请先保存稿件');controller.value=new AbortController();ai.text='';ai.state='waiting';try{await streamPost(`${apiBase}/api/wemedia/news/${id.value}/ai/continue`,{instruction:ai.instruction,targetLength:ai.targetLength,currentContent:form.content.filter(x=>x.type==='text').map(x=>x.value).join('\n')},auth.token,controller.value.signal,e=>{if(e.event==='meta')ai.state='generating';if(e.event==='chunk')ai.text+=String(e.data.text||e.data.content||'');if(e.event==='done')ai.state='done';if(e.event==='error')throw new Error(String(e.data.message||'AI 续写失败'))})}catch(e){ai.state=(e as Error).name==='AbortError'?'cancelled':'failed';if(ai.state==='failed')ElMessage.error(e instanceof ApiError?e.message:'AI 服务暂不可用')}finally{controller.value=undefined}}function stop(){controller.value?.abort()}function insert(){form.content.push({type:'text',value:ai.text});ElMessage.success('已插入正文，请保存后生效')}function copySuggestion(){void window.navigator.clipboard.writeText(ai.text)}onMounted(async()=>{[channels.value,materials.value]=await Promise.all([wmApi.channels(),wmApi.materials()]);if(id.value)fill(await wmApi.detail(id.value))});onBeforeUnmount(stop)</script>
<template><div class="stack"><section class="panel"><div class="toolbar"><h1 style="flex:1">{{id?'稿件详情':'新建稿件'}}</h1><el-tag v-if="news" :type="newsStatus[news.status]?.tone as any">{{statusLabel(news.status)}}</el-tag></div><el-alert v-if="news?.reason" type="error" :title="news.reason" show-icon/><el-form label-position="top" style="margin-top:16px"><el-form-item label="标题"><el-input v-model="form.title" maxlength="128" :disabled="!editable"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><el-form-item label="频道"><el-select v-model="form.channelId" :disabled="!editable"><el-option v-for="c in channels" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="标签"><el-input v-model="form.labels" :disabled="!editable"/></el-form-item></div><el-form-item label="发布时间（留空立即发布）"><el-date-picker v-model="form.publishTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" :disabled-date="(d:Date)=>d.getTime()<Date.now()-86400000" :disabled="!editable"/></el-form-item><el-form-item label="正文块"><div class="blocks" style="width:100%"><div v-for="(b,i) in form.content" :key="i" class="block-row"><el-select v-model="b.type" :disabled="!editable"><el-option label="文本" value="text"/><el-option label="图片" value="image"/></el-select><el-input v-if="b.type==='text'" v-model="b.value" type="textarea" :rows="5" :disabled="!editable"/><el-input v-else v-model="b.value" placeholder="图片 URL（建议从素材选择）" :disabled="!editable"/><el-button v-if="editable" text type="danger" @click="remove(i)">移除</el-button></div><div v-if="editable"><el-button @click="add('text')">加文本</el-button><el-button @click="add('image')">加图片</el-button></div></div></el-form-item><div v-if="editable" class="toolbar"><el-button type="primary" :loading="saving" @click="save">保存</el-button><el-button :disabled="saving" @click="submit">提交审核</el-button></div></el-form></section><section v-if="editable" class="panel"><h2>素材快捷插入</h2><div class="toolbar"><img v-for="m in materials" :key="m.id" :src="m.url" class="cover" style="width:110px;height:76px;cursor:pointer" @click="useMaterial(m)"></div></section><section v-if="editable" class="panel"><h2>AI 续写</h2><p class="meta">AI 输出仅作为建议；点击插入并手动保存后才会进入稿件。</p><div class="toolbar"><el-input v-model="ai.instruction" style="flex:1"/><el-input-number v-model="ai.targetLength" :min="50" :max="2000"/><el-button type="primary" :disabled="['waiting','generating'].includes(ai.state)" @click="generate">AI 续写</el-button><el-button v-if="['waiting','generating'].includes(ai.state)" @click="stop">停止</el-button></div><p class="meta">状态：{{({idle:'未开始',waiting:'等待模型…',generating:'正在生成…',done:'完成',cancelled:'已取消',failed:'失败'} as any)[ai.state]}}</p><div class="suggestion">{{ai.text||'生成内容将在这里逐块出现。'}}</div><div class="toolbar" style="margin-top:12px"><el-button :disabled="!ai.text" @click="insert">插入正文</el-button><el-button :disabled="!ai.text" @click="copySuggestion">复制</el-button></div></section><section v-if="news?.auditTrail?.length" class="panel"><h2>审核轨迹</h2><el-timeline><el-timeline-item v-for="a in news.auditTrail" :key="`${a.auditVersion}-${a.createdTime}`" :timestamp="a.createdTime"><strong>{{a.auditStage}} · {{a.decision}}</strong><p>{{a.reason}}</p><p class="meta">{{a.riskLevel}} {{a.riskTags?.join(' / ')}} <span v-if="a.confidence!=null">置信度 {{a.confidence}}</span></p></el-timeline-item></el-timeline></section></div></template>
